return [{
  json: $input.first() ? $input.first().json : {},
  binary: $('(ilL) Convert base64 string').first()?.binary || $('(206) Convert base64 string').first()?.binary
}];

// 1. Get the payload directly from the incoming data
const webhookBody = $input.first().json.body;

if (!webhookBody || !webhookBody.payload) {
    throw new Error("Webhook body or payload is missing. Make sure you are executing this node after the Webhook has received test data.");
}

const payload = webhookBody.payload;
const brand = payload.brand.brand_code;

// 2. Map Webflow API Tokens 
const API_TOKENS = {
  illumenate: '39621be88feaacaf3da2d1b2bbba90f43dd7c2b2cf9d10a8c2fcc6a70d5c593f', 
  lighting_206: '8a793908768d57e08301c20004930555e6bee903070e42ef4e32f78d923396fd'
};

// 3. Output the config for the rest of the workflow
return {
  json: {
    ...webhookBody, // Preserves the job, token, and hashes needed for the final Respond node
    brand: brand,
    webflow_collection_id: payload.brand.collections.Products,
    enriched_product: payload.product,
    webflow_api_token: API_TOKENS[brand]
  }
};

// Script to dynamically populate a product specification sheet with data from ERP and Webflow templates.

// 1. Safely extract the HTML string from 'Fetch Webflow Template'
const templateOutput = $('(206) Fetch Webflow Template').first().json;
let html = templateOutput.data || templateOutput.body || (typeof templateOutput === 'string' ? templateOutput : null);

if (!html) {
    throw new Error("HTML template string is missing from 'Fetch Webflow Template'. Ensure 'Response Format' is set to 'Text' in the Fetch Webflow Template node settings.");
}

// --- Strip out the Termly Cookie Consent script ---
html = html.replace(/<script[^>]*termly\.io[^>]*><\/script>/gi, '');

// --- Strip out Webflow's lazy loading so the PDF generator downloads all images instantly ---
html = html.replace(/loading="lazy"/gi, '');

// 2. Extract product from 'Get Product Info' node
const productInfo = $('Get Product Info').first().json;

const erpData = (productInfo.message && Array.isArray(productInfo.message.products))
    ? productInfo.message.products[0]
    : (productInfo.message || productInfo.data || productInfo);

if (!erpData || !erpData.product_name) {
    throw new Error("Could not extract product data from 'Get Product Info' node. Check the node output.");
}

const baseUrl = 'https://illumenatelighting.v.frappe.cloud';
const jobId = 'REV';

// 2a. Pre-process Image URLs
if (erpData.featured_image && !erpData.featured_image.startsWith('http')) {
    erpData.featured_image = baseUrl + erpData.featured_image;
}
if (erpData.custom_dimensions_image_2) {
    let dimUrl = erpData.custom_dimensions_image_2;
    if (!dimUrl.startsWith('http')) {
        dimUrl = 'https://app.illumenate.lighting' + (dimUrl.startsWith('/') ? '' : '/') + dimUrl;
    }
    erpData.custom_dimensions_image_2 = dimUrl;
}

// 2b. Map Certification Badge URLs
const certNames = [];
if (Array.isArray(erpData.certifications)) {
    erpData.certifications.forEach(c => {
        if (c.certification) certNames.push(c.certification);
        if (c.certification_details && c.certification_details.badge_image) {
            let url = c.certification_details.badge_image;
            c.certification_details.badge_image = url.startsWith('http') ? url : baseUrl + url;
        }
    });
}

if (erpData.specifications && certNames.length > 0) {
    const certSpec = erpData.specifications.find(s => s.spec_label === 'Certifications & Ratings');
    if (certSpec) {
        certSpec.spec_value = certNames.join(', ');
    }
}

// 2c. Reconstruct template_doctype and template_name
const templateMap = {
    tape_neon_template: 'ilL-Tape-Neon-Template',
    led_sheet_template: 'ilL-LED-Sheet-Template',
    kit_template: 'ilL-Extrusion-Kit-Template',
    fixture_template: 'ilL-Fixture-Template',
    driver_template: 'ilL-Driver-Template',
    controller_template: 'ilL-Controller-Template'
};

let resolved_template_doctype = null;
let resolved_template_name = null;

for (const [key, doctype] of Object.entries(templateMap)) {
    if (erpData[key]) {
        resolved_template_doctype = doctype;
        resolved_template_name = erpData[key];
        break;
    }
}

// 3. Inject global window.ERP_DATA and JOB_ID object into head
const dataScript = `<script>
    window.ERP_DATA = ${JSON.stringify(erpData).replace(/</g, '\\u003c')};
    window.JOB_ID = "${jobId}";
</script>`;

// 4. Inject client-side mapping script before </body>
const mappingScript = `<script>
(function populateSpecSheet() {
    const data = window.ERP_DATA;
    if (!data) return;

    function setText(id, value) {
        const el = document.getElementById(id);
        if (el && value != null && value !== '') el.innerText = value;
    }

    function setImg(id, url) {
        const el = document.getElementById(id);
        if (el && url) el.src = url;
    }

    function parseAllowedValues(val) {
        if (!val) return [];
        if (Array.isArray(val)) return val;
        if (typeof val === 'object') return [val];
        if (typeof val === 'string') {
            try { return JSON.parse(val); } catch (e) {
                try { return JSON.parse(val.replace(/[\\r\\n\\t]/g, '')); } catch (err) { return []; }
            }
        }
        return [];
    }

    const specArray = data.specifications || [];

    // --- A. CORE HEADERS & INTERACTIVE HEADER INPUTS ---
    setText('spec-prod-name', data.product_name);
    setText('spec-prod-category', data.product_type);
    setText('spec-prod-sublabel', data.sublabel);

    const beamSpec = specArray.find(s => s.spec_label === 'Beam Spread');
    if (beamSpec && beamSpec.spec_value) {
        setText('spec-beam-spread', beamSpec.spec_value);
    }

    const projInput = document.getElementById('spec-proj-name-input');
    if (projInput) projInput.innerHTML = '&nbsp;';
    const fixtInput = document.getElementById('spec-fixt-type-input');
    if (fixtInput) fixtInput.innerHTML = '&nbsp;';
    const locInput = document.getElementById('spec-location-input');
    if (locInput) locInput.innerHTML = '&nbsp;';

    // --- B. HERO & DIMENSION IMAGES ---
    setImg('spec-feat-img', data.featured_image);
    setImg('spec-dims-img', data.custom_dimensions_image_2);

    // --- C. DYNAMIC SPECIFICATIONS GRID ---
    const specSection = document.getElementById('spec-section-spec');

    if (specSection) {
        if (specArray.length === 0) {
            specSection.style.display = 'none';
        } else {
            specSection.style.display = ''; 

            const specGrid = document.querySelector('.spec-data-grid');
            if (specGrid) {
                const masterSpecItem = document.getElementById('spec-data-item');

                if (masterSpecItem) {
                    masterSpecItem.style.display = 'none'; 

                    const excludedLabels = [
                        "Output Options",
                        "Watts per Foot",
                        "Max Run Length",
                        "Max Footage per 100W Supply",
                        "Certifications & Ratings"
                    ];

                    const filteredSpecs = specArray.filter(spec => !excludedLabels.includes(spec.spec_label));

                    Array.from(specGrid.children).forEach(child => {
                        if (child !== masterSpecItem) child.remove();
                    });

                    filteredSpecs.forEach(spec => {
                        if (spec.spec_value) {
                            const itemClone = masterSpecItem.cloneNode(true);
                            itemClone.removeAttribute('id'); 
                            itemClone.style.display = ''; 

                            const titleEl = itemClone.querySelector('#spec-data-title');
                            const valueEl = itemClone.querySelector('#spec-data-value');

                            if (titleEl) {
                                titleEl.removeAttribute('id');
                                titleEl.innerText = spec.spec_label + ":";
                            }
                            if (valueEl) {
                                valueEl.removeAttribute('id');

                                /* --- HIGHLIGHT TAGGING FOR CCT SPEC LINE --- */
                                if (spec.spec_label === 'Light Color (CCT)') {
                                    valueEl.innerHTML = '';
                                    const cctTokens = spec.spec_value.split(',');
                                    for (let idx = 0; idx < cctTokens.length; idx++) {
                                        const cctVal = cctTokens[idx].trim();
                                        if (!cctVal) continue;
                                        const span = document.createElement('span');
                                        span.innerText = cctVal;
                                        const cleanCode = cctVal.toUpperCase().replace('00K', 'K');
                                        span.setAttribute('data-highlight', cleanCode);
                                        valueEl.appendChild(span);
                                        if (idx < cctTokens.length - 1) {
                                            valueEl.appendChild(document.createTextNode(', '));
                                        }
                                    }
                                } else {
                                    valueEl.innerText = spec.spec_value + (spec.spec_unit ? " " + spec.spec_unit : "");
                                }
                            }

                            specGrid.appendChild(itemClone);
                        }
                    });
                }
            }
        }
    }

    // --- D. DYNAMIC OUTPUT FLEXTABLE ---
    const flexContainer = document.getElementById('spec-dynamic-table-container');
    if (flexContainer && specArray.length > 0) {
        const cellTemplate = document.getElementById('spec-flextable-cell');

        if (cellTemplate) {
            cellTemplate.style.display = 'none'; 

            const targetLabels = [
                "Output Options",
                "Watts per Foot",
                "Max Run Length",
                "Max Footage per 100W Supply"
            ];

            const flexSpecs = specArray.filter(spec => targetLabels.includes(spec.spec_label));

            if (flexSpecs.length > 0) {
                flexContainer.style.display = '';

                Array.from(flexContainer.children).forEach(child => {
                    if (child !== cellTemplate) child.remove();
                });

                flexSpecs.sort((a, b) => (a.display_order || 0) - (b.display_order || 0));

                flexSpecs.forEach(spec => {
                    if (spec.spec_value) {
                        const clone = cellTemplate.cloneNode(true);
                        clone.removeAttribute('id');
                        clone.style.display = '';

                        const titleEl = clone.querySelector('#spec-flextable-title');
                        const valElTemplate = clone.querySelector('#spec-flextable-value');

                        if (titleEl) {
                            titleEl.removeAttribute('id');
                            if (spec.spec_label === "Output Options") {
                                titleEl.innerText = "Output (lm/ft)";
                            } else {
                                titleEl.innerText = spec.spec_label;
                            }
                        }

                        if (valElTemplate) {
                            const splitValues = spec.spec_value.split(',').map(v => v.trim()).filter(v => v);

                            splitValues.forEach((val, index) => {
                                const newVal = valElTemplate.cloneNode(true);
                                newVal.removeAttribute('id');
                                newVal.innerText = val;

                                /* --- ONLY TAG THE OUTPUT COLUMN TO DRIVE THE WHOLE ROW --- */
                                if (spec.spec_label === "Output Options") {
                                    const cleanCode = val.split(' ')[0].trim();
                                    newVal.setAttribute('data-highlight', cleanCode);
                                }

                                if (index === splitValues.length - 1) {
                                    newVal.classList.add('last-row');
                                }

                                clone.appendChild(newVal);
                            });

                            valElTemplate.remove();
                        }

                        flexContainer.appendChild(clone);
                    }
                });
            } else {
                flexContainer.style.display = 'none';
            }
        }
    }

    // --- D.5 PHOTOMETRICS & COLORIMETRY ---
    const photoSection = document.getElementById('spec-section-photo');
    if (photoSection) {
        if (data.photometric_image || (Array.isArray(data.photometric_data) && data.photometric_data.length > 0)) {
            photoSection.style.display = '';

            if (data.photometric_image) {
                let photoImgUrl = data.photometric_image;
                if (!photoImgUrl.startsWith('http')) {
                    photoImgUrl = 'https://app.illumenate.lighting' + (photoImgUrl.startsWith('/') ? '' : '/') + photoImgUrl;
                }
                setImg('spec-polar-img', photoImgUrl);
            } else {
                const polarImg = document.getElementById('spec-polar-img');
                if (polarImg) polarImg.style.display = 'none';
            }

            const photoTableWrapper = photoSection.querySelector('.photo-table-wrapper');
            if (photoTableWrapper) {
                const photoRowTemplate = document.getElementById('spec-photo-table-row');

                if (photoRowTemplate && Array.isArray(data.photometric_data) && data.photometric_data.length > 0) {
                    photoTableWrapper.style.display = '';
                    photoRowTemplate.style.display = 'none';
                    const photoTableParent = photoRowTemplate.parentNode;

                    Array.from(photoTableParent.children).forEach(child => {
                        if (child !== photoRowTemplate && child.classList.contains('spec-table-row')) {
                            child.remove();
                        }
                    });

                    const sortedPhotoData = data.photometric_data.sort((a, b) => (a.display_order || 0) - (b.display_order || 0));

                    sortedPhotoData.forEach(row => {
                        const rowClone = photoRowTemplate.cloneNode(true);
                        rowClone.removeAttribute('id');
                        rowClone.style.display = '';

                        const mtgEl = rowClone.querySelector('#spec-value-mtg');
                        const lightlvlEl = rowClone.querySelector('#spec-value-lightlvl');
                        const beamdiaEl = rowClone.querySelector('#spec-value-beamdia');

                        if (mtgEl) {
                            mtgEl.removeAttribute('id');
                            mtgEl.classList.add('no-wrap');
                            mtgEl.innerText = row.mounting_height || '';
                        }
                        if (lightlvlEl) {
                            lightlvlEl.removeAttribute('id');
                            lightlvlEl.classList.add('no-wrap');
                            lightlvlEl.innerText = row.light_level || '';
                        }
                        if (beamdiaEl) {
                            beamdiaEl.removeAttribute('id');
                            beamdiaEl.classList.add('no-wrap');
                            beamdiaEl.innerText = row.beam_diameter || '';
                        }

                        photoTableParent.appendChild(rowClone);
                    });
                } else {
                    photoTableWrapper.style.display = 'none';
                }
            }
        } else {
            photoSection.style.display = 'none';
        }
    }

    const colorSection = document.getElementById('spec-section-color');
    if (colorSection) {
        if (Array.isArray(data.colorimetry) && data.colorimetry.length > 0) {
            colorSection.style.display = '';
        } else {
            colorSection.style.display = 'none';
        }
    }

    // --- D.6 COMPATIBLE POWER SUPPLIES SECTION ---
    const powerSection = document.getElementById('spec-section-power');
    if (powerSection) {
        const powerSupplies = data.custom_compatible_power_supplies || [];

        if (Array.isArray(powerSupplies) && powerSupplies.length > 0) {
            powerSection.style.display = '';

            const tableWrapper = powerSection.querySelector('.power-table-wrapper');
            if (tableWrapper) {
                tableWrapper.style.display = '';

                const rowTemplate = document.getElementById('spec-compps-table-row');
                if (rowTemplate) {
                    rowTemplate.style.display = 'none';
                    const tableParent = rowTemplate.parentNode;

                    Array.from(tableParent.children).forEach(child => {
                        if (child !== rowTemplate && child.classList.contains('spec-table-row')) {
                            child.remove();
                        }
                    });

                    powerSupplies.forEach(ps => {
                        const rowClone = rowTemplate.cloneNode(true);
                        rowClone.removeAttribute('id');
                        rowClone.style.display = '';

                        /* --- HIGHLIGHT TAGGING FOR POWER SUPPLY ROWS --- */
                        if (ps.part_number) {
                            rowClone.setAttribute('data-highlight', ps.part_number);
                        }

                        const partNoEl = rowClone.querySelector('#ps-partno');
                        const inputEl = rowClone.querySelector('#ps-input');
                        const voltageEl = rowClone.querySelector('#ps-voltage');
                        const outVoltEl = rowClone.querySelector('#ps-outputvolt');
                        const maxWattEl = rowClone.querySelector('#ps-maxwatt');
                        const outCountEl = rowClone.querySelector('#ps-outputcount');
                        const locEl = rowClone.querySelector('#ps-location');

                        if (partNoEl) { partNoEl.removeAttribute('id'); partNoEl.innerText = ps.part_number || ''; }
                        if (inputEl) { inputEl.removeAttribute('id'); inputEl.innerText = ps.input_protocol || ''; }
                        if (voltageEl) { voltageEl.removeAttribute('id'); voltageEl.innerText = ps.voltagefrequency || ''; }
                        if (outVoltEl) { outVoltEl.removeAttribute('id'); outVoltEl.innerText = ps.output_voltage || ''; }
                        if (maxWattEl) { maxWattEl.removeAttribute('id'); maxWattEl.innerText = ps.max_wattage || ''; }
                        if (outCountEl) { outCountEl.removeAttribute('id'); outCountEl.innerText = ps.output_count || ''; }
                        if (locEl) { locEl.removeAttribute('id'); locEl.innerText = ps.location_rating || ''; }

                        tableParent.appendChild(rowClone);
                    });
                }
            }
        } else {
            powerSection.style.display = 'none';
        }
    }

    // --- E. CERTIFICATIONS & RATINGS BADGES (NO LAZY LOADING) ---
    let certBadges = [];
    if (Array.isArray(data.certifications)) {
        certBadges = data.certifications
            .filter(c => c.certification_details && c.certification_details['206_badge_dark'])
            .map(c => {
                let badgeCode = (c.certification_details && c.certification_details.certification_code) || c.certification || '';
                if (badgeCode === 'DryRated' || badgeCode.indexOf('Dry') !== -1) badgeCode = '20';
                else if (badgeCode === 'DampRated' || badgeCode.indexOf('Damp') !== -1) badgeCode = '54';
                else if (badgeCode === 'WetRated' || badgeCode.indexOf('Wet') !== -1) badgeCode = '67';
                return {
                    url: c.certification_details['206_badge_dark'],
                    code: badgeCode
                };
            });
    }

    const certWrapper = document.querySelector('.spec-cert-rate-wrapper');
    if (certWrapper && certBadges.length > 0) {
        certWrapper.innerHTML = ''; 
        certBadges.forEach(item => {
            const img = document.createElement('img');
            img.src = item.url;
            img.className = 'spec-cert-rate-icon';
            img.setAttribute('data-highlight', item.code);
            certWrapper.appendChild(img);
        });
    }

    // --- F. DYNAMIC CONFIGURATOR (HOW TO ORDER) ---
    const orderSection = document.getElementById('spec-section-ordering');
    if (orderSection) {
        if (Array.isArray(data.configurator_options) && data.configurator_options.length > 0) {
            const categoriesWrapper = document.getElementById('order-categories-wrapper') || document.querySelector('.order-categories-wrapper');

            const masterOrderGroup = document.getElementById('spec-order-group');
            const masterLengthGroup = document.getElementById('spec-length-group');
            const masterStartDirGroup = document.getElementById('spec-start-dir-group');
            const masterStartLengGroup = document.getElementById('spec-start-leng-group');
            const masterEndDirGroup = document.getElementById('spec-end-dir-group');
            const masterEndLengGroup = document.getElementById('spec-end-leng-group');

            const masterOrderItem = masterOrderGroup ? masterOrderGroup.querySelector('#spec-ordering-opt-item') : null;
            const masterLengthInput = masterLengthGroup ? masterLengthGroup.querySelector('#length-input') : null;
            const masterStartDirItem = masterStartDirGroup ? masterStartDirGroup.querySelector('#start-dir-item') : null;
            const masterStartLengItem = masterStartLengGroup ? masterStartLengGroup.querySelector('#start-leng-item') : null;
            const masterEndDirItem = masterEndDirGroup ? masterEndDirGroup.querySelector('#end-dir-item') : null;
            const masterEndLengItem = masterEndLengGroup ? masterEndLengGroup.querySelector('#end-leng-item') : null;

            if (masterOrderGroup) masterOrderGroup.remove();
            if (masterLengthGroup) masterLengthGroup.remove();
            if (masterStartDirGroup) masterStartDirGroup.remove();
            if (masterStartLengGroup) masterStartLengGroup.remove();
            if (masterEndDirGroup) masterEndDirGroup.remove();
            if (masterEndLengGroup) masterEndLengGroup.remove();

            if (masterOrderGroup && masterOrderItem) {
                const seriesGroupClone = masterOrderGroup.cloneNode(true);
                seriesGroupClone.style.display = ''; 
                seriesGroupClone.removeAttribute('id');

                const seriesCatTitleEl = seriesGroupClone.querySelector('#spec-ordering-cat-title');
                if (seriesCatTitleEl) {
                    seriesCatTitleEl.innerText = "SERIES*"; 
                }

                const seriesItemContainer = seriesGroupClone.querySelector('.ordering-opt-value-wrapper');
                if (seriesItemContainer) seriesItemContainer.innerHTML = '';

                const seriesItemClone = masterOrderItem.cloneNode(true);
                seriesItemClone.style.display = ''; 
                seriesItemClone.removeAttribute('id');

                const safeSlug = (data.product_slug || "").toUpperCase();
                seriesItemClone.setAttribute('data-step', '0');
                seriesItemClone.setAttribute('data-code', safeSlug);

                const seriesCodeTextEl = seriesItemClone.querySelector('#spec-ordering-code');
                if (seriesCodeTextEl) seriesCodeTextEl.innerText = safeSlug + ":";

                const seriesDescTextEl = seriesItemClone.querySelector('#spec-ordering-desc');
                if (seriesDescTextEl) seriesDescTextEl.innerText = data.product_name || "";

                if (seriesItemContainer) seriesItemContainer.appendChild(seriesItemClone);
                categoriesWrapper.appendChild(seriesGroupClone);

                const sortedConfig = data.configurator_options.sort((a, b) => a.option_step - b.option_step);

                for (let i = 0; i < sortedConfig.length; i++) {
                    let stepData = sortedConfig[i];
                    let currentValues = parseAllowedValues(stepData.allowed_values_json);

                    let groupClone, itemContainer, itemTemplate, titleEl, codeSelector, descSelector;

                    if (stepData.option_type === "Length" && masterLengthGroup && masterLengthInput) {
                        groupClone = masterLengthGroup.cloneNode(true);
                        titleEl = groupClone.querySelector('#spec-ordering-cat-title');
                        itemContainer = groupClone.querySelector('.ordering-opt-value-wrapper');
                        itemTemplate = masterLengthInput;
                        codeSelector = null;
                        descSelector = null;
                    } else if (stepData.option_label === "Start Feed Direction" && masterStartDirGroup && masterStartDirItem) {
                        groupClone = masterStartDirGroup.cloneNode(true);
                        titleEl = groupClone.querySelector('#spec-start-dir');
                        itemContainer = groupClone.querySelector('#start-dir-wrapper');
                        itemTemplate = masterStartDirItem;
                        codeSelector = '#start-dir-code';
                        descSelector = '#start-dir-desc';
                    } else if (stepData.option_label === "Start Feed Length" && masterStartLengGroup && masterStartLengItem) {
                        groupClone = masterStartLengGroup.cloneNode(true);
                        titleEl = groupClone.querySelector('#start-length');
                        itemContainer = groupClone.querySelector('#start-leng-wrapper');
                        itemTemplate = masterStartLengItem;
                        codeSelector = '#start-leng-code';
                        descSelector = '#start-leng-desc';
                    } else if (stepData.option_label === "End Feed Direction" && masterEndDirGroup && masterEndDirItem) {
                        groupClone = masterEndDirGroup.cloneNode(true);
                        titleEl = groupClone.querySelector('#spec-end-dir');
                        itemContainer = groupClone.querySelector('#end-dir-wrapper');
                        itemTemplate = masterEndDirItem;
                        codeSelector = '#end-dir-code';
                        descSelector = '#end-dir-desc';
                    } else if (stepData.option_label === "End Feed Length" && masterEndLengGroup && masterEndLengItem) {
                        groupClone = masterEndLengGroup.cloneNode(true);
                        titleEl = groupClone.querySelector('#end-length');
                        itemContainer = groupClone.querySelector('#end-leng-wrapper');
                        itemTemplate = masterEndLengItem;
                        codeSelector = '#end-leng-code';
                        descSelector = '#end-leng-desc';
                    } else {
                        groupClone = masterOrderGroup.cloneNode(true);
                        titleEl = groupClone.querySelector('#spec-ordering-cat-title');
                        itemContainer = groupClone.querySelector('.ordering-opt-value-wrapper');
                        itemTemplate = masterOrderItem;
                        codeSelector = '#spec-ordering-code';
                        descSelector = '#spec-ordering-desc';
                    }

                    if (groupClone && itemContainer && itemTemplate) {
                        groupClone.style.display = '';
                        groupClone.removeAttribute('id');

                        if (titleEl) {
                            let displayTitle = (stepData.option_label || stepData.option_type).toUpperCase();
                            if (displayTitle === "START FEED LENGTH" || displayTitle === "END FEED LENGTH") {
                                displayTitle = "LENGTH";
                            } else if (displayTitle === "LENGTH") {
                                displayTitle += " (INCHES)";
                            }
                            titleEl.innerText = displayTitle + (stepData.is_required ? "*" : "");
                        }

                        itemContainer.innerHTML = '';

                        if (stepData.option_type === "Length" && !codeSelector) {
                            const itemClone = itemTemplate.cloneNode(true);
                            itemClone.style.display = '';
                            itemClone.removeAttribute('id');
                            itemClone.setAttribute('data-step', stepData.option_step);
                            itemClone.setAttribute('data-code', 'Length');
                            itemContainer.appendChild(itemClone);
                        } else {
                            currentValues.forEach(valObj => {
                                const itemClone = itemTemplate.cloneNode(true);
                                itemClone.style.display = '';
                                itemClone.removeAttribute('id');
                                itemClone.setAttribute('data-step', stepData.option_step);
                                itemClone.setAttribute('data-code', valObj.code);

                                const codeTextEl = itemClone.querySelector(codeSelector);
                                if (codeTextEl) codeTextEl.innerText = valObj.code + ":";

                                const descTextEl = itemClone.querySelector(descSelector);
                                if (descTextEl) descTextEl.innerText = valObj.label || valObj.value;

                                itemContainer.appendChild(itemClone);
                            });
                        }
                        categoriesWrapper.appendChild(groupClone);
                    }
                }

                // --- 3. GENERATE EXAMPLE ORDERING CODE ---
                const exampleCodeOutput = document.getElementById('spec-ordering-example') || document.querySelector('.spec-ordering-example');
                if (exampleCodeOutput) {
                    let exampleSegments = [];
                    if (data.product_slug) exampleSegments.push(data.product_slug.toUpperCase());

                    let i = 0;
