        const originalPage = document.querySelector('.page-wrapper');
        document.body.appendChild(originalPage);

        Array.from(document.body.children).forEach(child => {
            if (!child.classList.contains('page-wrapper') && child.tagName !== 'SCRIPT') {
                child.style.display = 'none';
            }
        });

        const MAX_HEIGHT = 804;
        const mainWrapper = originalPage.querySelector('.spec-main-wrapper');

        let childrenToPaginate = Array.from(mainWrapper.children);

        if (childrenToPaginate.length === 1 && childrenToPaginate[0].children.length > 1) {
            childrenToPaginate = Array.from(childrenToPaginate[0].children);
        }

        mainWrapper.innerHTML = '';
        let currentPage = originalPage;
        let currentMain = mainWrapper;

        function createNewPage() {
            const newPage = originalPage.cloneNode(true);
            const newMain = newPage.querySelector('.spec-main-wrapper');
            newMain.innerHTML = '';
            document.body.appendChild(newPage);
            return { page: newPage, main: newMain };
        }

        childrenToPaginate.forEach(block => {
            if (block.id === 'spec-section-ordering') {
                const newPageObj = createNewPage(); 
                currentPage = newPageObj.page;
                currentMain = newPageObj.main;
            }

            currentMain.appendChild(block); 

            if (currentMain.scrollHeight > MAX_HEIGHT && block.id !== 'spec-section-ordering') {
                currentMain.removeChild(block); 
                const newPageObj = createNewPage(); 
                currentPage = newPageObj.page;
                currentMain = newPageObj.main;
                currentMain.appendChild(block); 
            }
        });
    }

    paginateSpecSheet();

    document.title = data.product_name + "_Spec Sheet";
})();
</script>`;

